import regionData from "@/data/shopCountryRegions.json";

/** First-level subdivisions per ISO country code, generated by
 * `scripts/generate-shop-country-regions.mjs` (Unicode CLDR; Ukraine curated). */
type RegionRecord = { code: string; en: string; uk?: string };

const REGIONS = regionData.regions as Record<string, RegionRecord[]>;

export type ShopCountryRegion = { code: string; name: string };

export function getShopCountryRegions(
  countryCode: string | null | undefined,
  locale: "ua" | "en"
): ShopCountryRegion[] {
  const list = REGIONS[String(countryCode ?? "").toUpperCase()] ?? [];
  // Ukrainian names only for Ukraine: an address abroad must stay in Latin
  // script for the foreign carrier.
  return list.map((region) => ({
    code: region.code,
    name: locale === "ua" && region.uk ? region.uk : region.en,
  }));
}

export function shopCountryHasRegions(countryCode: string | null | undefined) {
  return (REGIONS[String(countryCode ?? "").toUpperCase()]?.length ?? 0) > 0;
}
